import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { Link, MemoryRouter as Router, useLocation } from "react-router-dom";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Tabs.stories";
import Tab from "./Tab";
import Tabs from "./Tabs";

const { Basic } = composeStories(stories) as any;

describe("Tabs component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("selects the right tab", () => {
    render(
      <Tabs value={1}>
        <Tab>Panel 1</Tab>
        <Tab>Panel 2</Tab>
        <Tab>Panel 3</Tab>
      </Tabs>
    );
    const tabs = screen.getAllByRole("tab");
    expect(tabs[0]).toHaveAttribute("aria-selected", "false");
    expect(tabs[1]).toHaveAttribute("aria-selected", "true");
    expect(tabs[2]).toHaveAttribute("aria-selected", "false");
  });

  it("calls onChange with the right value", () => {
    const callback = jest.fn();
    render(
      <Tabs value={1} onChange={callback}>
        <Tab>Panel 1</Tab>
        <Tab>Panel 2</Tab>
        <Tab>Panel 3</Tab>
      </Tabs>
    );
    fireEvent.click(screen.getByRole("tab", { name: /Panel 1/i }));
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenCalledWith(expect.anything(), 0);
    fireEvent.click(screen.getByRole("tab", { name: /Panel 3/i }));
    expect(callback).toHaveBeenCalledTimes(2);
    expect(callback).toHaveBeenCalledWith(expect.anything(), 2);
  });

  it("scrolls to the selected tab when scrollable", async () => {
    const user = userEvent.setup();
    if (!HTMLElement.prototype.scrollIntoView) {
      Object.defineProperty(HTMLElement.prototype, "scrollIntoView", {
        value: jest.fn(),
        writable: true,
      });
    }
    const scrollSpy = jest
      .spyOn(HTMLElement.prototype, "scrollIntoView")
      .mockImplementation(() => {});
    const Wrapper = () => {
      const [value, setValue] = React.useState(0);
      return (
        <Tabs
          value={value}
          scrollable
          onChange={(event, nextValue) => setValue(nextValue)}
        >
          <Tab>Panel 1</Tab>
          <Tab>Panel 2</Tab>
          <Tab>Panel 3</Tab>
        </Tabs>
      );
    };
    render(<Wrapper />);
    await user.click(screen.getByRole("tab", { name: /Panel 3/i }));
    const tabs = screen.getAllByRole("tab");
    expect(tabs[2]).toHaveAttribute("aria-selected", "true");
    expect(scrollSpy).toHaveBeenCalledWith({
      block: "nearest",
      inline: "nearest",
    });
    scrollSpy.mockRestore();
  });

  it("moves focus with arrow keys and skips disabled tabs", async () => {
    const user = userEvent.setup();
    render(
      <Tabs value={0}>
        <Tab>Panel 1</Tab>
        <Tab disabled>Panel 2</Tab>
        <Tab>Panel 3</Tab>
      </Tabs>
    );
    const tabs = screen.getAllByRole("tab");
    tabs[0].focus();
    await user.keyboard("{ArrowRight}");
    expect(document.activeElement).toBe(tabs[2]);
    await user.keyboard("{ArrowLeft}");
    expect(document.activeElement).toBe(tabs[0]);
  });

  it("keeps focus when all other tabs are disabled", async () => {
    const user = userEvent.setup();
    render(
      <Tabs value={0}>
        <Tab>Panel 1</Tab>
        <Tab disabled>Panel 2</Tab>
        <Tab disabled>Panel 3</Tab>
      </Tabs>
    );
    const tabs = screen.getAllByRole("tab");
    tabs[0].focus();
    await user.keyboard("{ArrowRight}");
    expect(document.activeElement).toBe(tabs[0]);
  });

  it("activates the focused tab on Enter and Space", async () => {
    const user = userEvent.setup();
    const Wrapper = () => {
      const [value, setValue] = React.useState(0);
      return (
        <Tabs
          value={value}
          onChange={(event, nextValue) => setValue(nextValue)}
        >
          <Tab>Panel 1</Tab>
          <Tab>Panel 2</Tab>
        </Tabs>
      );
    };
    render(<Wrapper />);
    const tabs = screen.getAllByRole("tab");
    tabs[1].focus();
    await user.keyboard("{Enter}");
    expect(tabs[1]).toHaveAttribute("aria-selected", "true");
    await user.keyboard(" ");
    expect(tabs[1]).toHaveAttribute("aria-selected", "true");
  });

  it("warns when a Fragment is provided as a child", () => {
    const warnSpy = jest.spyOn(console, "warn").mockImplementation(() => {});
    render(
      <Tabs value={0}>
        <>
          <Tab>Panel 1</Tab>
        </>
        <Tab>Panel 2</Tab>
      </Tabs>
    );
    expect(warnSpy).toHaveBeenCalledWith(
      "[AIRBUS-DS] The Tabs component doesn't accept a Fragment as a child. Consider providing an array instead."
    );
    warnSpy.mockRestore();
  });

  it("passes through props", () => {
    render(
      <Tabs data-testid="tabs">
        <Tab data-testid="tab" />
      </Tabs>
    );
    expect(screen.getByTestId("tabs")).toBeTruthy();
    expect(screen.getByTestId("tab")).toBeTruthy();
  });

  it("allow using react router Link component", () => {
    const callback = jest.fn();
    const LocationDisplay = () => {
      const location = useLocation();
      return <div data-testid="location-display">{location.pathname}</div>;
    };
    render(
      <Router>
        <Tabs value={1} onChange={callback}>
          <Tab component={Link} to="panel1">
            Panel 1
          </Tab>
          <Tab component={Link} to="panel2">
            Panel 2
          </Tab>
          <Tab component={Link} to="panel3">
            Panel 3
          </Tab>
        </Tabs>
        <LocationDisplay />
      </Router>
    );
    fireEvent.click(screen.getByRole("tab", { name: /Panel 2/i }));
    expect(callback).toHaveBeenCalledTimes(1);
    expect(callback).toHaveBeenCalledWith(expect.anything(), 1);
    expect(screen.getByTestId("location-display")).toHaveTextContent("/panel2");
  });
});
